//! Native WebView2 window — wraps the HTTP server in a desktop window.
//!
//! Uses `wry` (Tauri team's WebView wrapper) which delegates to
//! WebView2 on Windows, WKWebView on macOS, and WebKitGTK on Linux.
//! The existing HTTP server runs in a background thread; the main
//! thread owns the window + event loop. Closing the window exits.

use std::time::{Duration, Instant};

use anyhow::{bail, Result};

/// Embedded app icon (256×256 RGBA PNG, generated by assets/gen_icon.py).
const ICON_PNG: &[u8] = include_bytes!("../assets/memex_icon.png");

/// Decode the embedded PNG once into RGBA bytes (shared by window + tray).
fn load_rgba() -> Option<(Vec<u8>, u32, u32)> {
    let decoder = png::Decoder::new(ICON_PNG);
    let mut reader = decoder.read_info().ok()?;
    let mut buf = vec![0u8; reader.output_buffer_size()];
    let frame = reader.next_frame(&mut buf).ok()?;
    // png crate: OutputInfo carries width/height directly
    Some((buf, frame.width, frame.height))
}

/// Build a `tao::window::Icon` from the embedded PNG.
fn load_tao_icon() -> Option<tao::window::Icon> {
    let (buf, w, h) = load_rgba()?;
    tao::window::Icon::from_rgba(buf, w, h).ok()
}

/// Build a `tray_icon::Icon` from the embedded PNG.
fn load_tray_icon() -> Option<tray_icon::Icon> {
    let (buf, w, h) = load_rgba()?;
    tray_icon::Icon::from_rgba(buf, w, h).ok()
}

/// Tray-only mode: HTTP server + system tray, no WebView2 window.
/// Memory ~15-25MB (vs ~390MB with full window).
pub fn run_tray_only(port: u16) -> Result<()> {
    let url = format!("http://127.0.0.1:{port}");

    // ── 1. Start HTTP server in background thread ──
    std::thread::Builder::new()
        .name("memex-http".into())
        .spawn(move || {
            if let Err(e) = crate::httpd::serve(port, false) {
                eprintln!("http server error: {e:#}");
            }
        })?;

    // ── 2. Wait for server to be ready (max 5s) ──
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        if std::net::TcpStream::connect(("127.0.0.1", port)).is_ok() {
            break;
        }
        if Instant::now() > deadline {
            bail!("HTTP server did not start within 5s on port {port}");
        }
        std::thread::sleep(Duration::from_millis(100));
    }

    // ── 3. Tray-only event loop (no WebView2 window) ──
    create_tray_only(&url)?;
    Ok(())
}

pub fn run_window(port: u16) -> Result<()> {
    let url = format!("http://127.0.0.1:{port}");

    // ── 1. Start HTTP server in background thread ──
    let server_handle = std::thread::Builder::new()
        .name("memex-http".into())
        .spawn(move || {
            if let Err(e) = crate::httpd::serve(port, false) {
                eprintln!("http server error: {e:#}");
            }
        })?;

    // ── 2. Wait for server to be ready (max 5s) ──
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        if std::net::TcpStream::connect(("127.0.0.1", port)).is_ok() {
            break;
        }
        if Instant::now() > deadline {
            bail!("HTTP server did not start within 5s on port {port}");
        }
        std::thread::sleep(Duration::from_millis(100));
    }

    // ── 3. Create native window + WebView (with browser fallback) ──
    match create_window(&url) {
        Ok(()) => {}
        Err(e) => {
            eprintln!("native window unavailable ({e:#}), opening browser instead");
            open_browser(&url);
            // Block until the HTTP server thread exits (Ctrl+C)
            let _ = server_handle.join();
            return Ok(());
        }
    }

    Ok(())
}

fn create_window(url: &str) -> Result<()> {
    use tao::{
        dpi::LogicalSize,
        event::{Event, WindowEvent},
        event_loop::{ControlFlow, EventLoop},
        window::WindowBuilder,
    };
    use tray_icon::menu::{Menu, MenuEvent, MenuId, MenuItem, PredefinedMenuItem};
    use tray_icon::{MouseButton, TrayIconBuilder, TrayIconEvent};
    use wry::WebViewBuilder;

    let event_loop = EventLoop::new();

    // ── Window ──
    let mut builder = WindowBuilder::new()
        .with_title("Memex — 本地知识库")
        .with_inner_size(LogicalSize::new(1200, 800))
        .with_min_inner_size(LogicalSize::new(800, 500));
    if let Some(icon) = load_tao_icon() {
        builder = builder.with_window_icon(Some(icon));
    }
    let window = builder.build(&event_loop)?;

    let webview = WebViewBuilder::new(&window)
        .with_url(url)
        .build()?;

    // ── System tray icon + context menu ──
    // Left-click → show window; right-click → context menu (automatic on Windows).
    let tray_menu = Menu::new();
    let browser_item = MenuItem::with_id(
        MenuId::new("browser"),
        "在浏览器中打开",
        true,
        None,
    );
    let search_item = MenuItem::with_id(
        MenuId::new("search"),
        "搜索文件",
        true,
        None,
    );
    let settings_item = MenuItem::with_id(
        MenuId::new("settings"),
        "设置",
        true,
        None,
    );
    let exit_item = MenuItem::with_id(
        MenuId::new("exit"),
        "退出",
        true,
        None,
    );
    let update_item = MenuItem::with_id(
        MenuId::new("update"),
        "检查更新",
        true,
        None,
    );
    tray_menu.append(&browser_item)?;
    tray_menu.append(&search_item)?;
    tray_menu.append(&settings_item)?;
    tray_menu.append(&PredefinedMenuItem::separator())?;
    tray_menu.append(&update_item)?;
    tray_menu.append(&exit_item)?;

    let tray_builder = TrayIconBuilder::new()
        .with_menu(Box::new(tray_menu))
        .with_tooltip("Memex — 本地知识库检索");
    let tray_icon = match load_tray_icon() {
        Some(icon) => tray_builder.with_icon(icon).build(),
        None => tray_builder.build(),
    };
    let _tray = tray_icon?; // keep alive for the process lifetime

    // Startup auto-check (5s delay, background)
    std::thread::spawn(|| {
        std::thread::sleep(std::time::Duration::from_secs(5));
        crate::update::auto_check("JohenDeng");
    });

    eprintln!(
        "Memex window ready → {url} (close hides to tray; left-click=show, right-click=menu)"
    );

    let base_url = url.to_string();

    // event_loop.run() blocks until exit; _tray + webview stay alive as locals.
    #[allow(unreachable_code)]
    {
        event_loop.run(move |event, _, control_flow| {
            *control_flow = ControlFlow::Wait;

            // ── Tray menu events (right-click context menu items) ──
            if let Ok(menu_event) = MenuEvent::receiver().try_recv() {
                match menu_event.id.as_ref() {
                    "browser" => {
                        open_browser(&base_url);
                    }
                    "search" => {
                        window.set_visible(true);
                        window.set_focus();
                        let _ = webview.evaluate_script("location.hash = '#/search'");
                    }
                    "settings" => {
                        window.set_visible(true);
                        window.set_focus();
                        let _ = webview.evaluate_script("location.hash = '#/settings'");
                    }
                    "update" => {
                        window.set_visible(true);
                        window.set_focus();
                        let _ = webview.evaluate_script("location.hash = '#/settings'; setTimeout(() => { if (typeof doCheckUpdate === 'function') doCheckUpdate(); }, 300)");
                    }
                    "exit" => {
                        crate::single_instance::release_lock();
                        *control_flow = ControlFlow::Exit;
                    }
                    _ => {}
                }
            }

            // ── Tray icon left-click → show window ──
            // Right-click is handled by the OS to show the context menu.
            if let Ok(tray_event) = TrayIconEvent::receiver().try_recv() {
                match tray_event {
                    TrayIconEvent::Click { button: MouseButton::Left, .. }
                    | TrayIconEvent::DoubleClick { button: MouseButton::Left, .. } => {
                        window.set_visible(true);
                        window.set_focus();
                    }
                    _ => {} // Right-click → OS shows menu automatically
                }
            }

            // ── Window events ──
            if let Event::WindowEvent {
                event: WindowEvent::CloseRequested,
                ..
            } = event
            {
                // Hide to tray instead of exiting
                window.set_visible(false);
            }
        });
        Ok(())
    }
}

fn create_tray_only(url: &str) -> Result<()> {
    use tao::{
        event_loop::{ControlFlow, EventLoop},
    };
    use tray_icon::menu::{Menu, MenuEvent, MenuId, MenuItem, PredefinedMenuItem};
    use tray_icon::{MouseButton, TrayIconBuilder, TrayIconEvent};

    let event_loop = EventLoop::new();

    // ── Tray icon + context menu (simplified: no window actions) ──
    let tray_menu = Menu::new();
    let browser_item = MenuItem::with_id(
        MenuId::new("browser"),
        "在浏览器中打开",
        true,
        None,
    );
    let exit_item = MenuItem::with_id(MenuId::new("exit"), "退出", true, None);
    let update_item = MenuItem::with_id(MenuId::new("update"), "检查更新", true, None);
    tray_menu.append(&browser_item)?;
    tray_menu.append(&update_item)?;
    tray_menu.append(&PredefinedMenuItem::separator())?;
    tray_menu.append(&exit_item)?;

    let tray_builder = TrayIconBuilder::new()
        .with_menu(Box::new(tray_menu))
        .with_tooltip("Memex — 本地知识库检索（后台模式）");
    let tray_icon = match load_tray_icon() {
        Some(icon) => tray_builder.with_icon(icon).build(),
        None => tray_builder.build(),
    };
    let _tray = tray_icon?;

    // Startup auto-check (5s delay, background)
    std::thread::spawn(|| {
        std::thread::sleep(std::time::Duration::from_secs(5));
        crate::update::auto_check("JohenDeng");
    });

    eprintln!("Memex tray-only mode → {url} (left-click=open browser, right-click=menu)");

    let base_url = url.to_string();

    event_loop.run(move |event, _, control_flow| {
        *control_flow = ControlFlow::Wait;

        // ── Tray menu events ──
        if let Ok(menu_event) = MenuEvent::receiver().try_recv() {
            match menu_event.id.as_ref() {
                "browser" => open_browser(&base_url),
                "update" => open_browser(&format!("{}/#/settings", base_url)),
                "exit" => {
                    crate::single_instance::release_lock();
                    *control_flow = ControlFlow::Exit;
                }
                _ => {}
            }
        }

        // ── Tray left-click → open browser (no window to show) ──
        if let Ok(tray_event) = TrayIconEvent::receiver().try_recv() {
            match tray_event {
                TrayIconEvent::Click { button: MouseButton::Left, .. }
                | TrayIconEvent::DoubleClick { button: MouseButton::Left, .. } => {
                    open_browser(&base_url);
                }
                _ => {}
            }
        }

        // No window events to handle in tray-only mode
        let _ = event;
    });
    Ok(())
}

fn open_browser(url: &str) {
    #[cfg(windows)]
    {
        let _ = std::process::Command::new("cmd")
            .args(["/C", "start", "", url])
            .spawn();
    }
    #[cfg(not(windows))]
    {
        let _ = std::process::Command::new("xdg-open").arg(url).spawn();
    }
}
